import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"打包与分发","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 插件程序集目录结构","slug":"_1-插件程序集目录结构","link":"#_1-插件程序集目录结构","children":[]},{"level":2,"title":"2. 自动化构建复制配置（PostBuild）","slug":"_2-自动化构建复制配置-postbuild","link":"#_2-自动化构建复制配置-postbuild","children":[]},{"level":2,"title":"3. 内嵌多语言资源文件","slug":"_3-内嵌多语言资源文件","link":"#_3-内嵌多语言资源文件","children":[]},{"level":2,"title":"4. 插件版本与元数据定义","slug":"_4-插件版本与元数据定义","link":"#_4-插件版本与元数据定义","children":[]},{"level":2,"title":"5. Release 构建与架构产物","slug":"_5-release-构建与架构产物","link":"#_5-release-构建与架构产物","children":[]}],"relativePath":"zh-CN/dev-guide/packaging.md","filePath":"zh-CN/dev-guide/packaging.md","lastUpdated":1791112464000}`),a={name:`zh-CN/dev-guide/packaging.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="打包与分发" tabindex="-1">打包与分发 <a class="header-anchor" href="#打包与分发" aria-label="Permalink to “打包与分发”">​</a></h1><p>本章节详细介绍 Lertaro 插件程序集的目录结构规范、第三方依赖库打包、多语言 JSON 资源内嵌以及自动化构建发布流程。</p><h2 id="_1-插件程序集目录结构" tabindex="-1">1. 插件程序集目录结构 <a class="header-anchor" href="#_1-插件程序集目录结构" aria-label="Permalink to “1. 插件程序集目录结构”">​</a></h2><p>Lertaro 在启动时会递归扫描应用程序根目录下的 <code>Plugins\\</code> 文件夹。为了保持环境纯净并避免不同插件之间的依赖库发生版本冲突，强烈建议为每个插件创建专属的子目录：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Lertaro/</span></span>
<span class="line"><span>├── Lertaro.App.exe</span></span>
<span class="line"><span>├── Lertaro.PluginSdk.dll</span></span>
<span class="line"><span>└── Plugins/</span></span>
<span class="line"><span>    └── MyCustomPlugin/</span></span>
<span class="line"><span>        ├── Lertaro.Plugins.MyCustomPlugin.dll   (插件主程序集)</span></span>
<span class="line"><span>        ├── ThirdParty.Managed.dll              (托管第三方依赖)</span></span>
<span class="line"><span>        └── NativeLibrary.dll                   (原生 C/C++ 依赖——平铺放置)</span></span></code></pre></div><ul><li><strong>依赖自动探测</strong>：Lertaro 的程序集加载器通过 <code>Assembly.LoadFrom</code> 机制加载主 DLL，.NET 运行时会自动从该子目录中解析并加载其同级依赖库，绝不会与其他插件相互干扰。</li><li><strong>原生依赖与 DLL 同级，而不是放在 <code>runtimes\\&lt;rid&gt;\\native</code> 下</strong>：随包发布的插件工程都设置了 <code>&lt;GenerateDependencyFile&gt;false&lt;/GenerateDependencyFile&gt;</code>，因此不会生成 <code>.deps.json</code>，运行时也就没有可据以解析 RID 子目录的依赖图。原生库必须能在应用程序基目录中被发现——所以要平铺复制。这也是两种架构要分别发布为独立产物、而不是合成一个安装包的原因：那个平铺的加载目录只能容纳一种架构的原生副本。</li><li><strong>原生文件容错</strong>：程序集扫描遇到非 .NET 的原生二进制文件（如 <code>e_sqlite3.dll</code>）时，加载器会以 <code>Debug</code> 级别记录后继续，而不是抛出误报的 <code>Error</code>。</li></ul><h2 id="_2-自动化构建复制配置-postbuild" tabindex="-1">2. 自动化构建复制配置（PostBuild） <a class="header-anchor" href="#_2-自动化构建复制配置-postbuild" aria-label="Permalink to “2. 自动化构建复制配置（PostBuild）”">​</a></h2><p>在插件工程的 <code>.csproj</code> 文件中配置 <code>PostBuild</code> 目标，可在每次编译成功后自动把产物复制到 Lertaro 的调试目录。仓库内的插件工程实际就是这样做的——注意<strong>平铺</strong>的目标目录，以及<strong>为 Service 准备的第二份复制</strong>，正是它让别名或翻译提供者同时可用于索引器与界面：</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\Service\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>如果你的插件在加载时需要第三方托管或原生依赖，请用同级的 <code>&lt;Copy&gt;</code> 项把它们复制到同一个目录。</p><h2 id="_3-内嵌多语言资源文件" tabindex="-1">3. 内嵌多语言资源文件 <a class="header-anchor" href="#_3-内嵌多语言资源文件" aria-label="Permalink to “3. 内嵌多语言资源文件”">​</a></h2><p>若你的插件实现了 <a href="./sdk/ui-extensions.html"><code>ITranslationProvider</code></a> 多语言接口，推荐将翻译 JSON 文件作为<strong>程序集内嵌资源</strong>打包，避免因外部文件遗失导致界面乱码：</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>按 <code>Resources/Translations/{culture}/{type}.json</code> 组织文件，其中 <code>{type}</code> 就是你传给 <code>TranslationService.LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 的 <code>typeName</code>。本仓库中每个插件都使用固定文件名 <strong><code>Plugin.json</code></strong>（<code>Resources/Translations/zh-CN/Plugin.json</code>、<code>Resources/Translations/en-US/Plugin.json</code>……）并传入 <code>&quot;Plugin&quot;</code>；<code>App.json</code> 并不是插件的约定——它只存在于 CoreExtensions 中，因为后者还要提供宿主自身的界面文案。语言文件夹跟随应用的七种界面语言；请求的语言没有对应文件夹时，翻译管理器会先回退到该插件自己支持的第一个语言，再回退到 <code>en-US</code>，都找不到才落到 <code>[key]</code> 占位文本。</p><h2 id="_4-插件版本与元数据定义" tabindex="-1">4. 插件版本与元数据定义 <a class="header-anchor" href="#_4-插件版本与元数据定义" aria-label="Permalink to “4. 插件版本与元数据定义”">​</a></h2><p>在 <code>.csproj</code> 中定义插件的版本号与程序集信息：</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;针对特定业务系统的高性能即时检索与动作扩展插件。&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>该版本号与描述信息会自动呈现在 Lertaro <strong>设置 → 插件</strong> 的管理卡片中，方便用户和开发者直观核验组件版本。</p><h2 id="_5-release-构建与架构产物" tabindex="-1">5. Release 构建与架构产物 <a class="header-anchor" href="#_5-release-构建与架构产物" aria-label="Permalink to “5. Release 构建与架构产物”">​</a></h2><p>在 Windows 上从仓库根目录运行 <code>make.bat</code> 前，需要安装 .NET SDK 和<a href="https://jrsoftware.org/isdl.php#v7" target="_blank" rel="noreferrer">64 位 Inno Setup 7</a>（脚本会校验编译器确实是 7.x）。脚本先后调用两次 <code>:build_arch</code>：一次 <code>ARCH=x64</code>（不带 RID 发布，一如既往），一次 <code>ARCH=arm64</code>（以 <code>-r win-arm64 --self-contained false</code> 交叉发布），在 <code>dist/</code> 产出四个文件：</p><ul><li><code>Lertaro-Setup.exe</code> 与 <code>Lertaro-Portable.zip</code>（x64）。</li><li><code>Lertaro-Setup-arm64.exe</code> 与 <code>Lertaro-Portable-arm64.zip</code>（arm64）。</li></ul><p>两种架构之所以发布为独立产物而不是合成一个安装包，是因为 BrowserData 插件携带原生库，而那个平铺、无 <code>.deps.json</code> 的加载目录只能容纳一种架构的原生副本（见脚本头部注释）。arm64 安装包与 x64 安装包在 <code>Installer/installer.iss</code> 中的差别包括：<code>ArchitecturesAllowed</code>（<code>arm64</code> 对 <code>x64compatible</code>）、<code>ArchitecturesInstallIn64BitMode</code>、<code>SetupArchitecture=x64</code>（仅 x64 设置）、内嵌的 .NET 桌面运行时文件与下载地址、<code>PublishDir</code> 以及输出文件名；每个包内的应用程序载荷都是各自架构的原生版本。发布工作流按这四个名字计算哈希并上传，<code>UpdateAssetSelector</code> 也按名字为旧版本匹配更新通道，改名字会让已装用户失联——请保持产物命名与 <code>make.bat</code>、<code>Installer/installer.iss</code> 以及发布工作流的资源清单一致。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};